<template>

<div>

<h2>Lista de Motocicletas</h2>

<table border="1">

<tr>

<th>Id</th>
<th>Placa</th>
<th>Marca</th>
<th>Cliente</th>

</tr>

<tr v-for="moto in motos" :key="moto.id">

<td>{{ moto.id }}</td>
<td>{{ moto.placa }}</td>
<td>{{ moto.marca }}</td>
<td>{{ moto.clienteId }}</td>

</tr>

</table>

</div>

</template>

<script>

import axios from "axios";

export default{

data(){

return{

motos:[]

}

},

mounted(){

this.listar();

},

methods:{

listar(){

axios.get("https://proyecto-production-b957.up.railway.app/api/motos")

.then(response=>{

this.motos=response.data;

})

.catch(error=>{

console.log(error);

});

}

}

}

</script>