<template>

    <div class="container">

        <h1>Formulario Motocicletas</h1>

        <form @submit.prevent="guardar">

<div class="form-group">
<label>Id</label>
<input type="number" v-model="id">
</div>

<div class="form-group">
<label>Placa</label>
<input type="text" v-model="placa">
</div>

<div class="form-group">
<label>Marca</label>
<input type="text" v-model="marca">
</div>

<div class="form-group">
<label>Cliente</label>
<input type="text" v-model="clienteId">
</div>

<br>

<button type="submit">Guardar</button>

<br><br>

<button type="button" @click="consultar">
Consultar
</button>

<br><br>

<button type="button" @click="actualizar">
Actualizar
</button>

<br><br>

<button type="button" @click="eliminar">
Eliminar
</button>

        </form>

    </div>

</template>

<script>

    import axios from "axios";

    export default{

        data(){

        return{

                id:"",
                placa:"",
                marca:"",
                clienteId:""

            }

        },

         methods:{

            guardar(){

         axios.post("https://proyecto-production-b957.up.railway.app/api/motos",{

placa:this.placa,
marca:this.marca,
clienteId:this.clienteId

            })

            .then(()=>{

                alert("Motocicleta guardada");

             this.id="";
             this.placa="";
             this.marca="";
                this.clienteId="";

                this.$emit("actualizar-tabla");

            })

         .catch(error=>{

            console.log(error);

            });

        },

        consultar(){

        axios.get("https://proyecto-production-b957.up.railway.app/api/motos/"+this.id)

            .then(response=>{

         this.placa=response.data.placa;
         this.marca=response.data.marca;
         this.clienteId=response.data.clienteId;

        })

        .catch(()=>{

     alert("No encontrada");

        });

        },

        actualizar(){

        axios.put("https://proyecto-production-b957.up.railway.app/api/motos/"+this.id,{

id:this.id,
placa:this.placa,
marca:this.marca,
clienteId:this.clienteId

        })

        .then(()=>{

        alert("Actualizada");

        this.$emit("actualizar-tabla");

        })

        .catch(()=>{

        alert("Error");

        });

        },

        eliminar(){

        axios.delete("https://proyecto-production-b957.up.railway.app/api/motos/"+this.id)

        .then(()=>{

        alert("Eliminada");

        this.$emit("actualizar-tabla");

        })

        .catch(()=>{

        alert("Error");

        });

        }

        }

    }

</script>